class GuardrailViolation(Exception):
    """
    Exception raised when a guardrail blocks a request or response.

    When constructed from a guardrail ``name`` and the scorer's ``rationale``, the resulting
    error message contains both (matching the pattern ``name.*rationale``). When no specific
    rationale is available, the message falls back to ``"blocked"``.
    """

    def __init__(
        self,
        message: str | None = None,
        *,
        name: str | None = None,
        rationale: str | None = None,
    ):
        if message is None:
            rationale = rationale or "blocked"
            if name is not None:
                message = f"Guardrail '{name}': {rationale}"
            else:
                message = rationale
        self.message = message
        super().__init__(message)


def _is_passing(value: Any) -> bool:
    """
    Interpret a scalar scorer value as passing or failing.

    ``True`` or a case-insensitive ``"yes"`` string is passing; ``False`` or any other string
    is failing. Any other type raises ``TypeError``.
    """
    # NB: bool must be checked before any int-like handling since bool subclasses int.
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.lower() == "yes"
    raise TypeError(f"Guardrail scorer returned an unexpected value type: {type(value).__name__}")


def _interpret_single(result: Any) -> tuple[bool, str | None]:
    """Interpret a single scorer result (``Feedback`` or raw scalar) as ``(passed, rationale)``."""
    if isinstance(result, Feedback):
        return _is_passing(result.value), result.rationale
    return _is_passing(result), None


def _interpret_result(result: Any) -> tuple[bool, str | None]:
    """
    Interpret a scorer result as ``(passed, rationale)``.

    A list of results is passing only if every item is individually passing; when an item
    fails, the returned rationale is that failing item's rationale.
    """
    if isinstance(result, list):
        for item in result:
            passed, rationale = _interpret_single(item)
            if not passed:
                return False, rationale
        return True, None
    return _interpret_single(result)


